import os
import json
from pathlib import Path
from typing import Dict, Any
from fastapi import HTTPException
from ollama import Client

class SecurityAgent:
    def __init__(self):
        self.git_keeper = self._init_git_keeper()
        self.ci_pipeline = self._init_ci_pipeline()
        self.vector_store = self._init_vector_store()

    def _init_git_keeper(self):
        """Initialise le gestionnaire git pour le contrôle de version"""
        return {
            "repo_path": str(Path(__file__).parent.parent.parent / "Promethee"),
            "last_commit": self._get_last_commit_hash(),
            "security_checkpoints": ["security_audit", "code_smith", "memory_gatekeeper"]
        }

    def _init_ci_pipeline(self):
        """Configure le pipeline CI/CD local"""
        return {
            "automated_checks": ["security_audit", "neural_compile", "vector_store"],
            "frequency": "daily",
            "last_run": self._get_last_ci_run_time()
        }

    def _init_vector_store(self):
        """Initialise le stockage vectoriel sécurisé"""
        return {
            "secure_mode": True,
            "consolidation_interval": 3600,  # 1 heure
            "memory_partitions": ["core", "agents", "grimoire"]
        }

    def _get_last_commit_hash(self):
        """Récupère le dernier commit hash depuis git"""
        try:
# [NEUTRALISÉ]             result = os.popen('git log -1 --format=%H').read()
            return result.strip() if result else "no_commit"
        except Exception:
            return "no_commit"

    def _get_last_ci_run_time(self):
        """Obtient le temps du dernier run CI"""
        try:
            ci_file = Path(__file__).parent.parent / "core" / "ci_pipeline.py"
            if ci_file.exists():
                return ci_file.stat().st_mtime
            return 0
        except Exception:
            return 0

    def perform_security_audit(self):
        """Exécute un audit de sécurité complet"""
        # Vérification des commits récents
        current_commit = self._get_last_commit_hash()
        if current_commit != self.git_keeper["last_commit"]:
            self._update_git_keeper(current_commit)

        # Vérification du pipeline CI
        if self._needs_ci_run():
            self._run_ci_pipeline()

        # Consolidation mémoire
        if self._needs_memory_consolidation():
            self._consolidate_memory()

    def _update_git_keeper(self, new_commit: str):
        """Mets à jour le gestionnaire git"""
        self.git_keeper["last_commit"] = new_commit
        self._save_git_state()

    def _save_git_state(self):
        """Sauvegarde l'état actuel du gestionnaire git"""
        state_file = Path(__file__).parent.parent / "core" / "git_state.json"
        try:
            with open(state_file, "w") as f:
                json.dump(self.git_keeper, f)
        except Exception as e:
            print(f"Erreur lors de la sauvegarde git_state: {str(e)}")

    def _needs_ci_run(self) -> bool:
        """Détermine si un run CI est nécessaire"""
        current_time = time.time()
        last_run = self.ci_pipeline["last_run"]
        return current_time - last_run > 86400  # 24 heures

    def _run_ci_pipeline(self):
        """Exécute le pipeline CI/CD local"""
        try:
            from core.ci_pipeline import run_pipeline
            result = run_pipeline()
            self.ci_pipeline["last_run"] = time.time()
            return result
        except Exception as e:
            print(f"Erreur lors de l'exécution du pipeline CI: {str(e)}")
            return {"status": "error", "details": str(e)}

    def _needs_memory_consolidation(self) -> bool:
        """Détermine si une consolidation mémoire est nécessaire"""
        return time.time() - self.vector_store["last_consolidation"] > 3600

