import json
from pathlib import Path
from typing import Dict, List, Optional
from uuid import uuid4
from datetime import datetime

class CouncilDebateManager:
    def __init__(self):
        self.debate_history = self._load_debate_history()
        self.contribution_cache = set()

    def _load_debate_history(self) -> Dict:
        """Charge l'historique des débats depuis le fichier de log"""
        history_path = Path("core/memory/vector_store/debate_history.json")
        if not history_path.exists():
            return {"sessions": []}

        try:
            with open(history_path, "r", encoding="utf-8") as f:
                return json.load(f)
        except json.JSONDecodeError:
            return {"sessions": []}

    def _save_debate_history(self, data: Dict) -> None:
        """Sauvegarde l'historique des débats"""
        history_path = Path("core/memory/vector_store/debate_history.json")
        with open(history_path, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)

    def validate_contribution(self, contribution: str) -> bool:
        """Vérifie si la contribution est unique et pertinente"""
        # Génération d'un hachage unique pour la contribution
        contribution_hash = hashlib.sha256(contribution.encode()).hexdigest()

        # Vérification contre l'historique des débats
        if contribution_hash in self.contribution_cache:
            return False

        # Vérification de la pertinence via l'historique
        for session in self.debate_history["sessions"]:
            if contribution in session["contributions"]:
                return False

        self.contribution_cache.add(contribution_hash)
        return True

    def record_contribution(self, agent_id: str, contribution: str) -> None:
        """Enregistre une contribution valide"""
        session_id = str(uuid4())
        timestamp = datetime.now().isoformat()

        self.debate_history["sessions"].append({
            "session_id": session_id,
            "timestamp": timestamp,
            "agent_id": agent_id,
            "contributions": [contribution]
        })

        self._save_debate_history(self.debate_history)
