import json
from pathlib import Path
from typing import Dict, List, Optional

class Council:
    def __init__(self):
        self.memory_path = Path("core/memory/vector_store.py")
        self.agents = self._load_agents()
        self.debate_history = self._load_debate_history()

    def _load_agents(self) -> Dict[str, str]:
        """Charger la liste des agents depuis le fichier vector_store.py"""
        try:
            with open(self.memory_path, "r", encoding="utf-8") as f:
                return json.load(f).get("agents", {})
        except Exception as e:
            print(f"Erreur lors du chargement des agents: {str(e)}")
            return {}

    def _load_debate_history(self) -> List[Dict]:
        """Charger l'historique des débats depuis le fichier vector_store.py"""
        try:
            with open(self.memory_path, "r", encoding="utf-8") as f:
                return json.load(f).get("debate_history", [])
        except Exception as e:
            print(f"Erreur lors du chargement de l'historique: {str(e)}")
            return []

    def add_to_debate_history(self, entry: Dict) -> None:
        """Ajouter un nouvel élément à l'historique des débats"""
        try:
            with open(self.memory_path, "r+", encoding="utf-8") as f:
                data = json.load(f)
                data["debate_history"].append(entry)
                f.seek(0)
                json.dump(data, f, indent=2)
        except Exception as e:
            print(f"Erreur lors de l'ajout à l'historique: {str(e)}")
